import React from 'react';
import { Link } from 'react-router-dom';

// Button Component
interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'ghost' | 'outline-dark';
  to?: string;
  className?: string;
}

export const Button: React.FC<ButtonProps> = ({ children, variant = 'primary', to, className = '', ...props }) => {
  const baseStyle = "inline-flex items-center justify-center px-10 py-4 text-base font-bold tracking-wider uppercase transition-all duration-300 rounded-none transform active:scale-95";

  const variants = {
    primary: "bg-brand-yellow text-white hover:bg-black hover:text-white border border-transparent", // Default is now Blue (yellow key)
    ghost: "bg-transparent text-white border border-white hover:bg-white hover:text-black",
    'outline-dark': "bg-transparent text-brand-text border border-gray-300 hover:bg-black hover:text-white"
  };

  const combinedClass = `${baseStyle} ${variants[variant]} ${className}`;

  if (to) {
    return (
      <Link to={to} className={combinedClass}>
        {children}
      </Link>
    );
  }

  return (
    <button className={combinedClass} {...props}>
      {children}
    </button>
  );
};

