// Modal Content Component
export const ProjectModal: React.FC<{ projectId: string; onClose: () => void }> = ({ projectId, onClose }) => {
  const project = PROJECTS.find(p => p.id === projectId);
  const [currentImg, setCurrentImg] = useState(0);

  if (!project) return null;

  const usedProducts = PRODUCTS.filter(p => project.relatedProductSlugs.includes(p.slug));

  return (
    <Modal isOpen={!!project} onClose={onClose}>
      <div className="grid grid-cols-1 lg:grid-cols-2 h-full min-h-[600px]">
        {/* Left: Gallery */}
        <div className="bg-black relative h-64 lg:h-auto">
          <img src={project.images[currentImg]} alt={project.title} className="w-full h-full object-contain" />
          {project.images.length > 1 && (
             <>
               <button onClick={() => setCurrentImg(prev => prev > 0 ? prev - 1 : project.images.length - 1)} className="absolute left-4 top-1/2 -translate-y-1/2 text-white bg-black/50 w-12 h-12 flex items-center justify-center hover:bg-brand-yellow hover:text-black text-xl">←</button>
               <button onClick={() => setCurrentImg(prev => prev < project.images.length - 1 ? prev + 1 : 0)} className="absolute right-4 top-1/2 -translate-y-1/2 text-white bg-black/50 w-12 h-12 flex items-center justify-center hover:bg-brand-yellow hover:text-black text-xl">→</button>
             </>
          )}
          <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-2">
            {project.images.map((_, idx) => (
              <button 
                key={idx} 
                onClick={() => setCurrentImg(idx)}
                className={`w-3 h-3 rounded-full ${currentImg === idx ? 'bg-brand-yellow' : 'bg-white/50'}`}
              />
            ))}
          </div>
        </div>

        {/* Right: Info */}
        <div className="p-8 lg:p-12 overflow-y-auto">
          <span className="text-brand-yellow text-sm font-bold tracking-widest uppercase mb-2 block">{CATEGORY_MAP[project.category]}</span>
          <h2 className="text-4xl font-bold mb-6">{project.title}</h2>

          <div className="grid grid-cols-2 gap-4 mb-8 text-lg">
             <div>
                <span className="block text-gray-400 mb-1">地點 Location</span>
                <span className="font-bold">{project.location}</span>
             </div>
             <div>
                <span className="block text-gray-400 mb-1">年份 Year</span>
                <span className="font-bold">{project.year}</span>
             </div>
          </div>

          <div className="mb-8">
