            <h4 className="font-bold text-xl mb-4 border-l-4 border-brand-yellow pl-3">使用材料/工法</h4>
            <div className="flex flex-wrap gap-2">
              {project.materials.map((m, i) => (
                <span key={i} className="bg-gray-100 px-4 py-2 text-base font-medium">{m}</span>
              ))}
            </div>
          </div>

          <div>
             <h4 className="font-bold text-xl mb-4 border-l-4 border-brand-yellow pl-3">相關產品</h4>
             <div className="space-y-4">
